import{_ as e,o as i,c as n,aA as l}from"./chunks/framework.BMzE2Z9R.js";const d=JSON.parse('{"title":"非公理控制","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/theory/nac/index.md","filePath":"nars/theory/nac/index.md","lastUpdated":1778399398000}'),r={name:"nars/theory/nac/index.md"};function s(c,a,o,_,t,p){return i(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="非公理控制" tabindex="-1">非公理控制 <a class="header-anchor" href="#非公理控制" aria-label="Permalink to &quot;非公理控制&quot;">​</a></h1><h2 id="简介-拟" tabindex="-1">简介（拟） <a class="header-anchor" href="#简介-拟" aria-label="Permalink to &quot;简介（拟）&quot;">​</a></h2><p>「非公理控制」英文全名为 <strong>Non-Axiomatic Control (NAC)</strong>，即「非公理推理的控制机制」。</p><p>「非公理控制」是NARS理论中一套将「非公理逻辑」从抽象理论带到具体系统的知识体系，可谓从「非公理逻辑」到「非公理推理系统」的最后一块拼图。</p><p>「非公理控制」之所以成为NARS理论中有别于「非公理逻辑」的一部分，主要原因有：</p><ol><li>虽然更涉及底层实现，但也有整体的逻辑结构——推理规则是具体的，但控制机制决定了推理的方向和聚焦点</li><li>不同版NARS实现有不同的控制机制方法，甚至是每一版NARS都有独特的控制机制实现——但也可以提炼出一些【足以写进教科书】的原则，比如「AIKR」「单步推理常数时间复杂度」等等</li><li>NAL中 越到上层（尤其是NAL 7～9），和控制机制的联系就越紧密——一些数据结构的设计和使用，已经超出了「从旧知识推理出新知识」的范畴，不能完全用Narsese、真值函数、逻辑公式描述</li></ol><p>（✨持续更新中，欢迎贡献内容）</p><h2 id="大致内容目录-拟" tabindex="-1">大致内容目录（拟） <a class="header-anchor" href="#大致内容目录-拟" aria-label="Permalink to &quot;大致内容目录（拟）&quot;">​</a></h2><p>🕒最后更新：【2024-08-30 20:44:42】</p><ul><li><a href="./nac_overview/">NARS控制机制概览</a></li><li><a href="./nac_principles/">NARS控制机制的总体原则</a><ul><li><a href="./nac_principles/aikr">知识资源相对不足</a></li><li><a href="./nac_principles/inference_step_o_n">常数时间的单步推理</a></li><li>…</li></ul></li><li><a href="./nal_and_nac/">NAL高层与NARS控制机制</a><ul><li><a href="./nal_and_nac/nal_7">NAL-7 时间推理：事件缓冲区系统</a></li><li><a href="./nal_and_nac/nal_8">NAL-8 目标推理：目标、事件与操作</a></li><li><a href="./nal_and_nac/nal_9">NAL-9 内省推理：全局指标与心理操作</a></li></ul></li><li><a href="./nac_classic_versions/">NARS经典版本的控制机制</a><ul><li><a href="./nac_classic_versions/opennars_15x">OpenNARS 1.5.x</a></li><li><a href="./nac_classic_versions/opennars_30x">OpenNARS 3.0.x/3.1.0</a></li><li><a href="./nac_classic_versions/opennars_31x">OpenNARS 3.1.x</a></li><li><a href="./nac_classic_versions/ona">ONA</a></li><li><a href="./nac_classic_versions/pynars">PyNARS</a></li><li>…</li></ul></li></ul><p>（✨持续更新中，欢迎贡献内容）</p>',11)])])}const f=e(r,[["render",s]]);export{d as __pageData,f as default};
